window.kbPageData["views/entry/k-1197f626c4e931b9"] = {"key":"entry/k-1197f626c4e931b9","state":{"route":"entry/k-1197f626c4e931b9"},"node":{"id":"k-1197f626c4e931b9","mode":"k","title":"加价率与折扣的计算基数","type":"概念与词义","domain":"数学","reading":"","intro":"","priority":100,"aliases":["加价率以进价为基数，折扣以折前售价为基数","加价率以进价为基数，折扣以原售价为基数"],"qs":["江苏 2024 A类 行测#53","江苏 2024 B类 行测#53"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":1,"directorySummary":"按进价加价时，加价额等于进价乘以加价率。打折时，折后价等于折前售价乘以折扣比例，7折对应70%。","review":{"definition":"按进价加价时，加价额等于进价乘以加价率。打折时，折后价等于折前售价乘以折扣比例，7折对应70%。","explanation":"路由器以100元进价为基数加价30%，得到折前售价130元，再以130元为基数打7折，得到折后售价91元。两阶段每件分别盈利30元和亏损9元。由7410元总利润和19%的成本利润率可得总成本39000元，共390件。若打折售出x件，则30×(390−x)−9x＝7410，解得110件。","references":[],"evidence":"加价30%出售，半年后将剩下的打7折全部售出","disposition":"独立词条","basis":"据原题和解析编释。","title":"加价率与折扣的计算基数","related":[],"examFocus":{"江苏 2024 A类 行测#53":"分清加价率、折扣和成本利润率各自的计算基数，再用折前、折后两批路由器的利润关系列式。"}},"readings":[{"origin":"k-1197f626c4e931b9","title":"加价率与折扣的计算基数","qs":["江苏 2024 B类 行测#53"],"definition":"按进价加价时，加价额等于进价乘以加价率。打折时，折后价等于折前售价乘以折扣比例，7折对应70%。","explanation":"路由器以100元进价为基数加价30%，得到折前售价130元，再以130元为基数打7折，得到折后售价91元。两阶段每件分别盈利30元和亏损9元。由7410元总利润和19%的成本利润率可得总成本39000元，共390件。若打折售出x件，则30×(390−x)−9x＝7410，解得110件。","evidence":"加价30%出售，半年后将剩下的打7折全部售出","doubt":"","references":[]},{"origin":"k-70fcd62e270bd742","title":"加价率与折扣的计算基数","qs":["江苏 2024 A类 行测#53"],"definition":"按进价加价销售时，加价率以进价为基数。打折时，折扣以折前售价为基数，打7折即按折前售价的70%出售。","explanation":"第53题中，进价100元加价30%后售价为130元，每个盈利30元。剩余商品以130元为基数打7折，售价为91元，每个亏损9元。总盈利7410元除以成本利润率19%，得总成本39000元，共390个。设打折售出x个，则30×(390−x)−9x=7410，解得110个。","evidence":"进价100元/个，加价30%出售，半年后将剩下的打7折全部售出","doubt":"","references":[]}]},"questions":{"江苏 2024 A类 行测#53":{"paper":"江苏 2024 A类 行测","n":53,"mod":"数量关系","src":["f8fec75f67d6d1ba5759.pdf",9],"asrc":["0126a1c8aceee632ea2b.pdf",16],"card":"40d0f589b0a7ef77358430da","links":[{"id":"k-1197f626c4e931b9","role":"解题依据","why":"依次使用两种计价基数，确定折前与折后的单位利润。"}]},"江苏 2024 B类 行测#53":{"paper":"江苏 2024 B类 行测","n":53,"mod":"数量关系","src":["0ae7ac475476e5635bd7.pdf",9],"asrc":["8dd171daee6fc74e9718.pdf",16],"card":"770d4485571e1877a817b09f","links":[{"id":"k-1197f626c4e931b9","role":"解题依据","why":"确定两个比例各自的计算基数，才能求出折前与折后的单件利润。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-1197f626c4e931b9":[["江苏 2024 A类 行测#53","江苏 2024 B类 行测#53"]]}};
